"""Interaction functions for the Treatment Delivery Table window UI in the Mosaiq application.
This window is displayed once a session has been selected for treatment from the Treatment Chart (RO Treat) window"""

from .objects.mosaiq_ro_treat_objects import ROTreat
from interops.libraries.squish_actions import CommonActions
from . import ro_treat as MosaiqROTreat
from . import common_popups as MosaiqCommonPopups
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME
from typing import Optional as opt
from interops.libraries.squish_actions.exceptions import FailedToFindObject

def __find_treatment_delivery_window() -> bool:
    """Searches for the treatment delivery window. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the ro_treat.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(ROTreat.treatment_Delivery_Table_Window) is not None else False


def __find_obj_by_ocr_with_special_characters_prefix(searchText: str, restrictOcrToList: bool = False, timeout:int=3000) -> opt[object]:
    """Helper function to add a special character that is typically added to the start of a text string
    found when using OCR (e.g. treatment field name) in the treatment field pane in the Treatment Delivery Table window.
    Tries to find the searched text string with several variations of prefixed special characters, where vertical table
    lines are misidentified by OCR as a number of different characters.

    Returns the object using OCR if the searchText is found in the Treatment Delivery Table window.

    -> Hidden function that should not be used outside the context of the treatment_delivery_table.py file context!

    :param str searchText: Text string to search for in the Treatment Delivery Table window
    :param bool restrictOcrToList: Restrict the OCR search to the treatment field pane only
    :return: Found object or None if not found
    :rtype: object
    """

    # Note: OCR sometimes misidentifies the vertical table line as some obscure characters next to text found in the treatment field pane
    possible_prefix_list = ["", "]", "}", "|", "R_|", ")", "Site Setup\\n"]
    if restrictOcrToList:
        search_area_obj = ROTreat.treatment_Delivery_inner_Pane
    else:
        search_area_obj = ROTreat.treatment_Delivery_Table_Window
    for prefix in possible_prefix_list:
        # Try prefixing a common character to the searched text string
        found_session_obj = CommonActions.get_object_by_ocr_text_in_object(search_area_obj, prefix + searchText, timeout)
        if found_session_obj is not None:
            return found_session_obj
    return None


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def check_treatment_delivery_table_window_appears(waitTimeout: int = 3) -> bool:
    """Check if the Treatment Delivery Table window is dispalyed
    """
    return CommonActions.wait_for_object_to_appear(ROTreat.treatment_Delivery_Table_Window, waitTimeout)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_on_select_button_on_treatment_delivery_window(ackSetupAlert: bool = True, ackFieldTreatedInLastFourHours: bool = False,
                                                        ackProjectedRxMisMatches: bool = False, ackPrescriptionDoseExceeded: bool = False,
                                                        doseOverridePassword="impac") -> None:
    """Click on select button on Treatment Delivery Table window

    :param bool ackSetupAlert: Press the close button the Setup Alert window if shown afer the
                               select button on the Treatment Delivery Table window is pressed
    :param bool ackFieldTreatedInLastFourHours: Acknowledge the Field Treated in Last Four Hours warning if shown
    :param bool ackProjectedRxMisMatches: Acknowledge the Projected Rx Mismatches warning if shown
    :param bool ackPrescriptionDoseExceeded: Acknowledge the Prescription Dose Exceeded warning if shown
    :param str doseOverridePassword: The password to be entered in the Fx or Total Dose Override Approval window
    """
    CommonActions.left_click_object(ROTreat.treatment_Delivery_Table_select_Button)
    # Acknowledge the Setup Alert window by pressing the close button if shown
    if ackSetupAlert:
        MosaiqCommonPopups.click_close_button_setup_alert()
    if ackFieldTreatedInLastFourHours:
        MosaiqCommonPopups.acknowledge_field_treated_within_last_four_hours_warning()
    if ackPrescriptionDoseExceeded:
        if MosaiqCommonPopups.acknowledge_prescription_dose_will_be_exceeded_dialog():
            total_dose_override_approval(doseOverridePassword)
    if ackProjectedRxMisMatches:
        if MosaiqCommonPopups.acknowledge_projected_rx_mismatches_warning():
            # Fx Dose Override Approval
            fx_dose_override_approval(doseOverridePassword)
    CommonActions.wait_for_object_to_appear(ROTreat.verify_setup_Window)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_on_close_button_on_treatment_delivery_window(ackAllFieldsNotTreatedAlert: bool = True) -> None:
    """Click on close button on Treatment Delivery Table window

    :param bool ackAllFieldsNotTreatedAlert: True if the All Fields not treated alert should be acknowledged
    """
    CommonActions.left_click_object(ROTreat.treatment_Delivery_Table_close_Button)
    # Acknowledge the "All Fields NOT Treated, Exit?" dialog by selecting the Yes button if shown
    if ackAllFieldsNotTreatedAlert:
        MosaiqCommonPopups.acknowledge_all_fields_not_treated_warning()
    CommonActions.wait_for_object_to_disappear(ROTreat.treatment_Delivery_Table_Window)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def click_on_field_from_list_on_Treatment_delivery(field:str, setDefaultSelectionToStart: bool = False,
                                                   fieldSelectRetries: int = 3) -> None:
    """Click on treatment field from the list using OCR

    :param str field: Field name to be selected
    :param bool setDefaultSelectionToStart: Set the default selection to the first field in the list
    :param int fieldSelectRetries: Number of times to scroll down the treatment field list
    """
    if __find_treatment_delivery_window():
        try:
            if setDefaultSelectionToStart:
                CommonActions.press_home_key()
            field_obj = __find_obj_by_ocr_with_special_characters_prefix(field, restrictOcrToList=False)
            CommonActions.click_screen_area_object(field_obj)
        except SyntaxError:
            # Try scrolling down the treatment field list by pressing the Pg Down keyboard button
            # a number of times as specified by fieldSelectRetries
            for i in range(fieldSelectRetries):
                try:
                    CommonActions.press_key_down_arrow()
                    field_obj = __find_obj_by_ocr_with_special_characters_prefix(field, restrictOcrToList=True)
                    CommonActions.click_screen_area_object(field_obj)
                    break
                except SyntaxError:
                    pass


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def fx_dose_override_approval(password: str, waitTimeout: int = 3000) -> bool:
    """Enter the approval password in the Fx Dose Override Approval window and select the OK button

    :param str password: The password to be entered in the Fx Dose Override Approval window
    :param int waitTimeout: The amount of time to wait for the Fx Dose Override Approval window to appear
    :return: True if the Fx Dose Override Approval window is successfully closed (approved), False otherwise
    """
    try:
        CommonActions.find_object(ROTreat.fx_Dose_Override_Approval_Window, timeout=waitTimeout)
        CommonActions.type_in_textfield(ROTreat.fx_Dose_Override_Approval_Window_Password_Edit_Field, password)
        CommonActions.left_click_object(ROTreat.fx_Dose_Override_Approval_Window_Ok_Button)
        return CommonActions.wait_for_object_to_disappear(ROTreat.fx_Dose_Override_Approval_Window)
    except FailedToFindObject:
        return False


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def total_dose_override_approval(password: str, waitTimeout: int = 3000) -> bool:
    """Enter the approval password in the Total Dose Override Approval window and select the OK button

    :param str password: The password to be entered in the Total Dose Override Approval window
    :param int waitTimeout: The amount of time to wait for the Total Dose Override Approval window to appear
    :return: True if the Total Dose Override Approval window is successfully closed (approved), False otherwise
    """
    try:
        CommonActions.find_object(ROTreat.total_Dose_Override_Approval_Window, timeout=waitTimeout)
        CommonActions.type_in_textfield(ROTreat.total_Dose_Override_Approval_Window_Password_Edit_Field, password)
        CommonActions.left_click_object(ROTreat.total_Dose_Override_Approval_Window_Ok_Button)
        return CommonActions.wait_for_object_to_disappear(ROTreat.total_Dose_Override_Approval_Window)
    except FailedToFindObject:
        return False


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_treatment_delivery_table_context_menu() -> None:
    """Opens the context menu in the Treatment Delivery Table window using the right-mouse click
    """
    if __find_treatment_delivery_window():
        CommonActions.right_click_object(ROTreat.treatment_Delivery_inner_Pane)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_load_reference_data_from_tdt_context_menu() -> None:
    """Selects the Load Reference Data menu item from the Treatment Delivery Table context menu.
    This function assumes that the context menu has already been opened using the
    open_treatment_delivery_table_context_menu() function.
    """
    CommonActions.left_click_object(ROTreat.treatment_Delivery_Table_Load_Reference_Data_Context_Menu_Item)


@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def initiate_load_reference_data_from_tdt_with_shortcut() -> None:
    """Starts the Load Reference Data process from the Treatment Delivery Table window using the keyboard shortcut
    """
    CommonActions.press_key_sequence("<Ctrl+J>")